    public heap: Heap,
    public roots: (HeapObject | null)[],
    public young: number,
    public promotionAge: number,
  ) {
    this.half = young / 2;
  }
  inactive(): Pair {
    const start = this.half - this.base;
    return [start, start + this.half];
  }
  oldBlocks() {
    return freeBlocks(this.heap.objects.values(), this.young, this.heap.size);
  }
  freeList() {
    const blocks = this.oldBlocks();
    const length = this.base + this.half - this.top;
    if (length > 0) blocks.unshift({ address: this.top, length });
    return blocks;
  }
  writeBarrier(o: HeapObject, v: HeapObject | null) {
    if (o.address < this.young) return;
    this.barriers++;
    if (v && v.address < this.young && !this.remembered.has(o)) {
      this.remembered.add(o);
      this.remembers++;
    }
  }
  claim(size: number) {
    if (this.top + size > this.base + this.half) return null;
    const address = this.top;
    this.top += size;
    return address;
  }
  collect(rec: CollectionRecord) {
    const major = rec.kind === 'major' || rec.kind === 'full';
    if (major) {
      const marked = mark(this.roots, rec);
      for (const o of sweep(this.heap, marked, rec, (o) => o.address >= this.young)) {
        this.remembered.delete(o);
      }
