        const address = firstFit(this.oldBlocks(), o.size);
        if (address === null) return false;
        o.address = address;
        addObject(rec.promoted, o);
      } else {
        o.address = top;
        top += o.size;
      }
      addObject(rec.moved, o);
      if (!major) addObject(rec.live, o);
      queue.push(o);
      return true;
