    for (const root of this.roots) if (!evacuate(root)) return false;
    for (const o of [...this.remembered].sort((a, b) => a.address - b.address)) {
      rec.work += 1 + o.pointers;
      for (const v of o.fields) if (!evacuate(v)) return false;
    }
    for (let i = 0; i < queue.length; i++) {
      const o = queue[i];
      rec.work += o.size + o.pointers;
      for (const v of o.fields) if (!evacuate(v)) return false;
    }
    for (const o of remaining) {
      this.heap.objects.delete(o.number);
      addObject(rec.freed, o);
    }
    this.base = dest;
    this.top = top;
    this.remembered = new Set(
      [...this.heap.objects.values()].filter(
        (o) =>
