      if (!this.collect(rec)) return null;
      rec.after = freeAmount(this.freeList());
      record(rec);
      address = this.claim(size);
      if (address !== null) return address;
    }
    return null;
  }
}

export type Pair = [number, number];
export interface HeapObject {
  number: number;
  pointers: number;
  data: number;
  size: number;
