    const f = row.split(' ');
    switch (f[0]) {
      case 'HEAP':
        settings.heap = Number(f[1]);
        break;
      case 'WIDTH':
        settings.width = Number(f[1]);
        break;
      case 'MAPS':
        settings.maps = new Set(f.slice(1));
        break;
      case 'MMU':
        settings.windows = f.slice(1).map(Number);
        break;
      case 'COLLECTOR': {
        if (f[2] === 'GENERATIONAL') {
          settings.collectors.push({
            name: f[1],
            type: f[2],
            young: Number(f[3]),
            age: Number(f[4]),
          });
        } else if (
          f[2] === 'MARK_SWEEP' ||
          f[2] === 'MARK_COMPACT' ||
          f[2] === 'COPYING' ||
          f[2] === 'REFCOUNT'
